import heapq
from itertools import combinations, product


def _routes(data, coupon_rule, minimum_duration, use_discount):
    required = data.get("required", [])
    required_bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = required_bit.get(source, 0)
    start = data["start"]
    limit = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    initial_state = (source, initial_mask, 0)
    distance = {initial_state: start}
    queue = [(start, source, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distance.get(state) != time:
            continue
        if (node == data["target"] and mask == full
                and (coupon_rule == "at_most" or used == limit)):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], used)]
            if used < limit:
                duration = edge["duration"]
                if use_discount:
                    duration = max(minimum_duration,
                                   duration - edge.get("discount", 0))
                choices.append((duration, used + 1))
            next_mask = mask | required_bit.get(edge["v"], 0)
            for duration, next_used in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_used)
                if arrival < distance.get(next_state, float("inf")):
                    distance[next_state] = arrival
                    heapq.heappush(queue, (arrival, edge["v"], next_mask, next_used))
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    chosen = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(numerator):
        if mode == "half_up":
            return (numerator + 5000) // 10000
        return numerator // 10000

    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _resolver(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = []
    for name in names:
        versions = sorted(row["version"] for row in packages[name])
        choices.append([None] + versions)

    best_key = None
    best = None
    for values in product(*choices):
        selected = {name: version for name, version in zip(names, values)
                    if version is not None}
        valid = True
        for name, version in selected.items():
            if version in blocked.get(name, []):
                valid = False
                break
            if name in pins and version != pins[name]:
                valid = False
                break
        if not valid:
            continue
        rows = {}
        for name, version in selected.items():
            rows[name] = next(row for row in packages[name]
                              if row["version"] == version)

        # Build dependency edges and verify every active range.
        graph = {name: [] for name in selected}
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                if child not in selected or not dep["min"] <= selected[child] <= dep["max"]:
                    valid = False
                    break
                graph[name].append(child)
            if not valid:
                break
        if not valid:
            continue

        for name, bounds in data["roots"].items():
            if name not in selected or not bounds[0] <= selected[name] <= bounds[1]:
                valid = False
                break
        if not valid:
            continue

        # Installed packages must be exactly the dependency closure of roots.
        reachable = set()
        stack = list(data["roots"])
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph.get(name, []))
        if reachable != set(selected):
            continue

        finished, active = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in finished:
                return True
            active.add(name)
            for child in graph.get(name, []):
                if not visit(child):
                    return False
            active.remove(name)
            finished.add(name)
            return True

        if not all(visit(name) for name in graph):
            continue
        vector = tuple(selected.get(name, -1) for name in names)
        if best_key is None or vector < best_key:
            best_key = vector
            best = selected

    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _schedule(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    if not mandatory.issubset({job["id"] for job in jobs}) or len(mandatory) > k:
        return {"error": "impossible"}

    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None
    for group in combinations(jobs, k):
        ids = [job["id"] for job in group]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in group:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(name, 0) <= high
               for name, (low, high) in quotas.items()):
            continue
        intervals = sorted((job["start"], job["end"]) for job in group)
        if any(intervals[i][0] < intervals[i - 1][1]
               for i in range(1, len(intervals))):
            continue
        value = sum(job["value"] for job in group)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value
                or (value == best_value and sorted_ids < best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": lambda d: _routes(d, "at_most", 2, False),
    "component_02": lambda d: _routes(d, "exact", 2, True),
    "component_03": lambda d: _routes(d, "at_most", 1, True),
    "component_04": lambda d: _routes(d, "exact", 1, False),
    "component_05": lambda d: _routes(d, "at_most", 2, False),
    "component_06": _ledger,
    "component_07": _resolver,
    "component_08": _schedule,
}

